import { addDays, addMonths, addYears } from 'date-fns';
import type { Dispatch } from 'react';

import { _validateCalendarSelection } from './calendar-validation.js';
import type { TimeframeV2 } from '../../../../core/types/time.js';
import { type FormFieldMessagesReducerAction } from '../../../forms-core/state/formfield-messages-state-reducer.js';
import { _getTimeValueFromSimpleValue } from '../../../forms-core/time/helpers.js';
import { _isTimeframeV2 } from '../../../forms-core/time/types.js';
import type {
  _CalendarReducerAction,
  _CalendarState,
} from '../types/shared-types.js';
import {
  _getDateFromSelection,
  _getPosition,
  _getWeekStartOrEnd,
} from '../utils/helpers.js';

/** Calendar reducer */
export function reducer(
  state: _CalendarState,
  action: _CalendarReducerAction,
  handleValidation: Dispatch<FormFieldMessagesReducerAction>,
  onChange?: (date: TimeframeV2 | string | null) => void,
): _CalendarState {
  switch (action.type) {
    case 'activeDateChange':
      return {
        ...state,
        activeDate: action.payload.activeDate,
        currentView: action.payload.changeToView ?? state.currentView,
      };
    case 'typeChanged':
      return { ...state, ...action.payload };
    case 'currentViewChange':
      return { ...state, currentView: action.payload };
    case 'isCalendarBodyFocusedChange':
      return { ...state, isCalendarBodyFocused: action.payload };
    case 'weekStartsOnChange':
      return { ...state, weekStartsOn: action.payload };
    case 'selectionChanged': {
      const newTimeValue = _getTimeValueFromSimpleValue(
        action.payload,
        state.timeOffset,
        state.position,
      );

      const newSelectedDate = _getDateFromSelection(
        state.selectedDate,
        state.type,
        newTimeValue,
        state.position,
      );

      // The onChange should be triggered after updating the state to prevent a bad setState() call during rendering.
      requestAnimationFrame(() => {
        if (!newSelectedDate) {
          return onChange?.(null);
        }

        if (
          _isTimeframeV2(newSelectedDate, state.type) &&
          'from' in newSelectedDate &&
          'to' in newSelectedDate
        ) {
          return onChange?.(newSelectedDate as TimeframeV2);
        }

        if ('value' in newSelectedDate) {
          onChange?.(newSelectedDate.value);
        }
      });

      return state;
    }
    case 'navigateCurrentView': {
      let newActiveDate: Date;
      const { amount, unit } = action.payload;
      const affectedScale = unit ?? state.currentView;
      const realAmount =
        typeof amount === 'number'
          ? amount
          : _getWeekStartOrEnd(amount, state.activeDate, state.weekStartsOn);

      switch (affectedScale) {
        case 'day':
          newActiveDate = addDays(state.activeDate, realAmount);
          break;
        case 'month':
          newActiveDate = addMonths(state.activeDate, realAmount);
          break;
        case 'year':
          newActiveDate = addYears(state.activeDate, realAmount);
          break;
      }

      return {
        ...state,
        activeDate: newActiveDate,
      };
    }
    case 'hoveredItemChanged': {
      return { ...state, hoveredDate: action.payload };
    }
    case 'valueChanged': {
      const updatedValue = action.payload;

      const internalError = _validateCalendarSelection(
        updatedValue,
        state,
        handleValidation,
      );

      const activeDate = _isTimeframeV2(updatedValue, state.type)
        ? updatedValue.from?.absoluteDate
        : updatedValue?.absoluteDate;

      return {
        ...state,
        selectedDate: updatedValue,
        activeDate: activeDate ? new Date(activeDate) : state.today,
        hoveredDate: null,
        position: _getPosition(state.position, updatedValue),
        errorId: internalError,
      };
    }
    default:
      // Should never happen
      throw new Error('The dispatched action does not exist.');
  }
}
